//! SwissKnife fee-cap rejection and explicitly uncapped manual payment flow.
//!
//! SwissKnife is a custodial wallet connected to lnd-bob. These tests verify
//! that l402-swissknife can pay invoices generated by Aperture and complete
//! the full L402 handshake.

use regtest_helpers::*;
use serde_json::Value;

// These tests share one funded wallet; balance assertions must exclude the manual payment.
static WALLET: tokio::sync::Mutex<()> = tokio::sync::Mutex::const_new(());

macro_rules! skip_if_no_swissknife {
    ($backend:ident) => {
        skip_if_no_regtest!();
        let $backend = match swissknife_backend().await {
            Some(b) => b,
            None => {
                eprintln!("SKIP: SwissKnife not available");
                return;
            }
        };
    };
}

#[tokio::test]
async fn capped_payments_are_rejected_without_debiting_wallet() {
    skip_if_no_swissknife!(backend);
    let _wallet_guard = WALLET.lock().await;
    use l402_proto::{ClientError, LnBackend};
    let balance = backend.get_balance().await.unwrap();
    assert!(!backend.supports_fee_limit());
    let client = build_l402_client(backend.clone());
    for _ in 0..2 {
        assert!(matches!(
            client.get(&format!("{}/api/data", l402_server_url())).await,
            Err(ClientError::FeeLimitUnsupported)
        ));
    }
    assert_eq!(client.total_spent().await, 0);
    assert!(client.receipts().await.is_empty());
    assert_eq!(backend.get_balance().await.unwrap(), balance);
}

#[tokio::test]
async fn explicit_uncapped_payment_can_complete_manual_l402_flow() {
    skip_if_no_swissknife!(backend);
    let _wallet_guard = WALLET.lock().await;
    let url = format!("{}/api/data", l402_server_url());
    let http = reqwest::Client::new();
    let challenge = http.get(&url).send().await.unwrap();
    let challenge = l402_proto::L402Challenge::from_header(
        challenge.headers()["www-authenticate"].to_str().unwrap(),
    )
    .unwrap();
    let payment = backend
        .pay_invoice_unbounded(&challenge.invoice)
        .await
        .unwrap();
    assert_eq!(payment.amount_sats, 100);
    assert!(!payment.payment_hash.is_empty());
    let token = l402_proto::L402Token::new(challenge.macaroon, payment.preimage);
    let response = http
        .get(&url)
        .header("Authorization", token.to_header_value())
        .send()
        .await
        .unwrap();
    assert_eq!(response.status().as_u16(), 200);
    let body: Value = response.json().await.unwrap();
    assert_eq!(body["ok"], true);
}

#[tokio::test]
async fn swissknife_nonexistent_endpoint() {
    skip_if_no_swissknife!(backend);
    let _wallet_guard = WALLET.lock().await;

    let client = build_l402_client(backend);
    let url = format!("{}/api/nonexistent", l402_server_url());
    let response = client.get(&url).await.unwrap();

    assert_eq!(response.status().as_u16(), 404);
    assert!(!response.paid());
}
